62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
110	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
111	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
112	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
119	        prepareNewOwner(ownerFieldsDto, registrationDate);
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        owner.setRegistrationDate(registrationDate);
123	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
124	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
125	        assignHousehold(owner, ownerFieldsDto);
126	        this.clinicService.saveOwner(owner);
127	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
128	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
129	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
130	            ownerMapper.membershipLevel(owner));
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        ownerDto.setBulkSignupWarning(bulkSignupWarning(registrationDate));
133	        headers.setLocation(UriComponentsBuilder.newInstance()
134	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
135	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
141	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
142	        if (currentOwner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        currentOwner.setAddress(ownerFieldsDto.getAddress());
146	        currentOwner.setCity(ownerFieldsDto.getCity());
147	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
148	        currentOwner.setLastName(ownerFieldsDto.getLastName());
149	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
150	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
151	        this.clinicService.saveOwner(currentOwner);
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Transactional
157	    @Override
158	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        this.clinicService.deleteOwner(owner);
164	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        HttpHeaders headers = new HttpHeaders();
175	        Pet pet = petMapper.toPet(petFieldsDto);
176	        owner.setId(ownerId);
177	        pet.setOwner(owner);
178	        pet.getType().setName(null);
179	        this.clinicService.savePet(pet);
180	        PetDto petDto = petMapper.toPetDto(pet);
181	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
182	            .buildAndExpand(pet.getId()).toUri());
183	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
189	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
190	        if (currentOwner != null) {
191	            Pet currentPet = this.clinicService.findPetById(petId);
192	            if (currentPet != null) {
193	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
194	                currentPet.setName(petFieldsDto.getName());
195	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
196	                this.clinicService.savePet(currentPet);
197	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
198	            }
199	        }
200	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
206	        HttpHeaders headers = new HttpHeaders();
207	        Visit visit = visitMapper.toVisit(visitFieldsDto);
208	        Pet pet = new Pet();
209	        pet.setId(petId);
210	        visit.setPet(pet);
211	        this.clinicService.saveVisit(visit);
212	        VisitDto visitDto = visitMapper.toVisitDto(visit);
213	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
214	            .buildAndExpand(visit.getId()).toUri());
215	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
216	    }
217	
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
222	        Owner owner = this.clinicService.findOwnerById(ownerId);
223	        if (owner != null) {
224	            Pet pet = owner.getPet(petId);
225	            if (pet != null) {
226	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
227	            }
228	        }
229	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	    }
231	
232	    /**
233	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
234	     * The address is normalized in place (so a required-field check that follows rejects an
235	     * address blank after normalization), the required fields are checked, the telephone and
236	     * email are normalized in place, and the resulting telephone is rejected when it already
237	     * belongs to another owner. Each rule
238	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
239	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
240	     * to be mapped and saved.
241	     *
242	     * @param ownerFieldsDto the submitted owner fields, normalized in place
243	     */
244	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
245	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
246	        validateRequiredFields(ownerFieldsDto);
247	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
248	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
249	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
250	        rejectDuplicateHousehold(ownerFieldsDto);
251	        rejectCityAtCapacity(ownerFieldsDto.getCity());
252	        rejectDailyLimitExceeded(registrationDate);
253	    }
254	
255	    /**
256	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
257	     * falls on a business day. The date supplied on the request is used when present, otherwise the
258	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
259	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
260	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
261	     * membership number's year segment, the per-day create limit) is computed against.
262	     *
263	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
264	     * @return the effective registration date rolled forward to the next business day
265	     */
266	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
267	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
268	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
269	        return toBusinessDay(effective);
270	    }
271	
272	    /**
273	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
274	     * following Monday, while a weekday is returned unchanged.
275	     *
276	     * @param date the date to adjust
277	     * @return the same date when it is a weekday, otherwise the next Monday
278	     */
279	    private LocalDate toBusinessDay(LocalDate date) {
280	        java.time.DayOfWeek day = date.getDayOfWeek();
281	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
282	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
283	        }
284	        return date;
285	    }
286	
287	    /**
288	     * The maximum number of owners that may be created on a single day. Once this many owners
289	     * already carry today's {@code registrationDate}, no further owner may be created today.
290	     */
291	    private static final long DAILY_OWNER_LIMIT = 100L;
292	
293	    /**
294	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
295	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
296	     * date the new owner would be stored with, so owners are capped per business day. When the limit
297	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
298	     * advice renders as a 429 Too Many Requests response.
299	     *
300	     * @param registrationDate the adjusted business-day registration date of the owner being created
301	     */
302	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
303	        long count = this.clinicService.findAllOwners().stream()
304	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
305	            .count();
306	        if (count >= DAILY_OWNER_LIMIT) {
307	            throw new DailyOwnerLimitExceededException(registrationDate);
308	        }
309	    }
310	
311	    /**
312	     * The number of owners that may carry a single day's {@code registrationDate} before that day
313	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
314	     * the create and read responses report {@code bulkSignupWarning} true for that date.
315	     */
316	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
317	
318	    /**
319	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
320	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
321	     * count is taken against the same adjusted date owners are stored with, mirroring the
322	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
323	     *
324	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
325	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
326	     */
327	    private boolean bulkSignupWarning(LocalDate registrationDate) {
328	        if (registrationDate == null) {
329	            return false;
330	        }
331	        long count = this.clinicService.findAllOwners().stream()
332	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
333	            .count();
334	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
335	    }
336	
337	    /**
338	     * The maximum number of owners a single city may hold. Once a city already contains this
339	     * many owners, no further owner may be created in it.
340	     */
341	    private static final long CITY_OWNER_CAPACITY = 50L;
342	
343	    /**
344	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
345	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
346	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
347	     * which the exception advice renders as a 409 Conflict response.
348	     *
349	     * @param city the city of the owner being created
350	     */
351	    private void rejectCityAtCapacity(String city) {
352	        long count = this.clinicService.findAllOwners().stream()
353	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
354	            .count();
355	        if (count >= CITY_OWNER_CAPACITY) {
356	            throw new CityCapacityExceededException(city);
357	        }
358	    }
359	
360	    /**
361	     * Builds the customer code assigned to a newly created owner. The code is formatted as
362	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
363	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
364	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
365	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
366	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
367	     *
368	     * @param city the owner's city
369	     * @param lastName the owner's last name
370	     * @return the formatted customer code
371	     */
372	    private String nextCustomerCode(String city, String lastName) {
373	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
374	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
375	        long sequence = this.clinicService.findAllOwners().stream()
376	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
377	            .count() + 1L;
378	        return String.format("%s-%s-%04d", city3, last3, sequence);
379	    }
380	
381	    /**
382	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
383	     * with the owner being created, compared case-insensitively. The count is taken before the
384	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
385	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
386	     *
387	     * @param firstName the first name of the owner being created
388	     * @param lastName the last name of the owner being created
389	     * @return the number of pre-existing owners sharing the same first and last name
390	     */
391	    private int countNamesakes(String firstName, String lastName) {
392	        return (int) this.clinicService.findAllOwners().stream()
393	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
394	                && lastName.equalsIgnoreCase(existing.getLastName()))
395	            .count();
396	    }
397	
398	    /**
399	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
400	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
401	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
402	     * the names of every offending field, which the exception advice renders as a 400 response
403	     * with an {@code errors} array.
404	     *
405	     * @param ownerFieldsDto the submitted owner fields
406	     */
407	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
408	        List<String> missing = new ArrayList<>();
409	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
410	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
411	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
412	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
413	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
414	        if (!missing.isEmpty()) {
415	            throw new RequiredFieldsMissingException(missing);
416	        }
417	    }
418	
419	    private void addIfBlank(List<String> missing, String fieldName, String value) {
420	        if (value == null || value.isBlank()) {
421	            missing.add(fieldName);
422	        }
423	    }
424	
425	    /**
426	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
427	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
428	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
429	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
430	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
431	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
432	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
433	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
434	     *
435	     * @param telephone the submitted telephone value
436	     * @return the normalized E.164 telephone
437	     */
438	    private String normalizeTelephone(String telephone) {
439	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
440	        String e164;
441	        if (cleaned.startsWith("+")) {
442	            e164 = "+" + cleaned.substring(1);
443	        } else {
444	            String national = cleaned;
445	            if (national.startsWith("0")) {
446	                national = national.substring(1);
447	            }
448	            e164 = "+61" + national;
449	        }
450	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
451	            throw new InvalidFieldsException(List.of("telephone"));
452	        }
453	        return e164;
454	    }
455	
456	    /**
457	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
458	     * and a domain containing at least one dot, none of the parts holding whitespace or a
459	     * second {@code @}.
460	     */
461	    private static final java.util.regex.Pattern EMAIL_PATTERN =
462	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
463	
464	    /**
465	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
466	     * accepted and returned unchanged. When present it must be a syntactically valid address;
467	     * the value is stored and returned lower-cased. When present but invalid an
468	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
469	     * response naming the {@code email} field.
470	     *
471	     * @param email the submitted email value, or {@code null} when omitted
472	     * @return the lower-cased email, or {@code null} when none was supplied
473	     */
474	    private String normalizeEmail(String email) {
475	        if (email == null) {
476	            return null;
477	        }
478	        String trimmed = email.trim();
479	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
480	            throw new InvalidFieldsException(List.of("email"));
481	        }
482	        return canonicalEmail(trimmed);
483	    }
484	
485	    /**
486	     * Reduces an email to the canonical form used both to store it and to compare it against
487	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
488	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
489	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
490	     * value read back off an existing owner without risk of rejecting it. This is the single
491	     * definition of email identity: two emails denote the same address exactly when they
492	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
493	     * an email already on an existing owner can be compared for equality after both pass through
494	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
495	     *
496	     * @param email the email to canonicalize, or {@code null} when none was supplied
497	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
498	     */
499	    private String canonicalEmail(String email) {
500	        if (email == null) {
501	            return null;
502	        }
503	        return email.trim().toLowerCase(java.util.Locale.ROOT);
504	    }
505	
506	    /**
507	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
508	     * The telephone is stored in its normalized E.164 form, so a plain equality check
509	     * against every owner's telephone compares E.164 values. When a match is found a
510	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
511	     * 409 Conflict response.
512	     *
513	     * @param telephone the normalized telephone of the owner being created
514	     */
515	    private void rejectDuplicateTelephone(String telephone) {
516	        boolean taken = this.clinicService.findAllOwners().stream()
517	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
518	        if (taken) {
519	            throw new DuplicateTelephoneException(telephone);
520	        }
521	    }
522	
523	    /**
524	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
525	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
526	     * for how that identity is compared). A request may bypass this rule by setting
527	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
528	     * When a household mate is found and the request did not opt in a
529	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
530	     * Conflict response.
531	     *
532	     * @param ownerFieldsDto the submitted owner fields
533	     */
534	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
535	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
536	            return;
537	        }
538	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
539	        if (taken) {
540	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
541	        }
542	    }
543	
544	    /**
545	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
546	     * set to {@code true}. The identifier is derived deterministically from the owner's
547	     * household identity (its {@code lastName} and {@code address}, see
548	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
549	     * the same stable value. The new owner receives that value, and any existing household mates
550	     * that do not yet carry it are updated so the whole household shares one identifier. When the
551	     * request did not opt in the owner is left without a household identifier.
552	     *
553	     * @param owner the newly created owner, mutated in place with its household identifier
554	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
555	     */
556	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
557	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
558	            return;
559	        }
560	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
561	        owner.setHouseholdId(householdId);
562	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
563	            if (!householdId.equals(mate.getHouseholdId())) {
564	                mate.setHouseholdId(householdId);
565	                this.clinicService.saveOwner(mate);
566	            }
567	        }
568	    }
569	
570	    /**
571	     * Derives the stable {@code householdId} shared by every owner in the household identified by
572	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
573	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
574	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
575	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
576	     *
577	     * @param lastName the household's last name
578	     * @param address the household's address
579	     * @return the deterministic household identifier
580	     */
581	    private String householdIdFor(String lastName, String address) {
582	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
583	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
584	        try {
585	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
586	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
587	            StringBuilder sb = new StringBuilder();
588	            for (int i = 0; i < 8; i++) {
589	                sb.append(String.format("%02X", digest[i]));
590	            }
591	            return "HH-" + sb;
592	        }
593	        catch (java.security.NoSuchAlgorithmException e) {
594	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
595	        }
596	    }
597	
598	    /**
599	     * Counts the owners that belong to the household identified by the given {@code householdId},
600	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
601	     * of owners, so after a create it reflects the household's size including the newly persisted
602	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
603	     * household and yields {@code 0}.
604	     *
605	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
606	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
607	     */
608	    private int countHouseholdMembers(String householdId) {
609	        if (householdId == null) {
610	            return 0;
611	        }
612	        return (int) this.clinicService.findAllOwners().stream()
613	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
614	            .count();
615	    }
616	
617	    /**
618	     * Finds an existing owner that shares a household with the given {@code lastName} and
619	     * {@code address}. When several owners match, the first one encountered is returned.
620	     *
621	     * @param lastName the last name to match on
622	     * @param address the address to match on
623	     * @return the first owner sharing the household, or empty when none exists
624	     */
625	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
626	        return findHouseholdMates(lastName, address).stream().findFirst();
627	    }
628	
629	    /**
630	     * Finds every existing owner that shares a household with the given {@code lastName} and
631	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
632	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
633	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
634	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
635	     * every rule that reasons about households.
636	     *
637	     * @param lastName the last name to match on
638	     * @param address the address to match on
639	     * @return the owners sharing the household, in encounter order (possibly empty)
640	     */
641	    private List<Owner> findHouseholdMates(String lastName, String address) {
642	        String normalizedLastName = collapseWhitespace(lastName);
643	        String normalizedAddress = normalizeAddress(address);
644	        return this.clinicService.findAllOwners().stream()
645	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
646	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
647	            .toList();
648	    }
649	
650	    /**
651	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
652	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
653	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
654	     *
655	     * @param value the value to collapse, or {@code null}
656	     * @return the whitespace-collapsed value, never {@code null}
657	     */
658	    private String collapseWhitespace(String value) {
659	        if (value == null) {
660	            return "";
661	        }
662	        return value.trim().replaceAll("\\s+", " ");
663	    }
664	
665	    /**
666	     * Common street-type abbreviations expanded during address normalization, keyed by their
667	     * upper-cased token.
668	     */
669	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
670	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
671	
672	    /**
673	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
674	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
675	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
676	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
677	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
678	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
679	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
680	     * everywhere an address is stored or compared.
681	     *
682	     * @param address the submitted address value, or {@code null}
683	     * @return the normalized address, never {@code null}
684	     */
685	    private String normalizeAddress(String address) {
686	        if (address == null) {
687	            return "";
688	        }
689	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
690	        if (collapsed.isEmpty()) {
691	            return "";
692	        }
693	        String[] tokens = collapsed.split(" ");
694	        StringBuilder sb = new StringBuilder(collapsed.length());
695	        for (int i = 0; i < tokens.length; i++) {
696	            if (i > 0) {
697	                sb.append(' ');
698	            }
699	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
700	        }
701	        return sb.toString();
702	    }
703	}
