36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
56	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given lastName and address already exists";
57	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
58	    private static final String ERROR_DAILY_LIMIT_EXCEEDED = "The maximum number of owners has already been created today";
59	
60	    /**
61	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
62	     * class.
63	     *
64	     * @param e     Object referring to the thrown exception.
65	     * @param status HTTP response status.
66	     * @param url URL request.
67	     */
68	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
69	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
70	        problemDetail.setType(URI.create(url.toString()));
71	        problemDetail.setTitle(e.getClass().getSimpleName());
72	        problemDetail.setDetail(detail);
73	        problemDetail.setProperty("timestamp", Instant.now());
74	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
75	        return problemDetail;
76	    }
77	
78	    /**
79	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
80	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
81	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
82	     * would catch it and report an authorization failure as a 500.
83	     *
84	     * @param e The {@link AccessDeniedException} to propagate
85	     * @throws AccessDeniedException always
86	     */
87	    @ExceptionHandler(AccessDeniedException.class)
88	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
89	        throw e;
90	    }
91	
92	    /**
93	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
94	     *
95	     * @param e The {@link Exception} to be handled
96	     * @param request {@link HttpServletRequest} object referring to the current request.
97	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
98	     */
99	    @ExceptionHandler(Exception.class)
100	    @ResponseBody
101	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
102	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
103	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
104	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
105	        return ResponseEntity.status(status).body(detail);
106	    }
107	
108	    /**
109	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
110	     * method returns a 404 Not Found status if an entity does not exist.
111	     *
112	     * @param e The {@link DataIntegrityViolationException} to be handled
113	     * @param request {@link HttpServletRequest} object referring to the current request.
114	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
115	     */
116	    @ExceptionHandler(DataIntegrityViolationException.class)
117	    @ResponseBody
118	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
119	        logger.warn("Data integrity violation at {} {}: {}",
120	            request.getMethod(),
121	            request.getRequestURI(),
122	            e.getMessage());
123	        logger.debug("Data integrity violation stacktrace", e);
124	        HttpStatus status = HttpStatus.NOT_FOUND;
125	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
126	        return ResponseEntity.status(status).body(detail);
127	    }
128	
129	    /**
130	     * Handles exception thrown by Bean Validation on controller methods parameters
131	     *
132	     * @param e The {@link MethodArgumentNotValidException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
135	     */
136	    @ExceptionHandler(MethodArgumentNotValidException.class)
137	    @ResponseBody
138	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
139	        HttpStatus status = HttpStatus.BAD_REQUEST;
140	        BindingResult bindingResult = e.getBindingResult();
141	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
142	        if (bindingResult.hasErrors()) {
143	            logger.debug("Validation error at {} {}: {}",
144	                request.getMethod(),
145	                request.getRequestURI(),
146	                bindingResult.getFieldErrors());
147	            detail.setProperty("schemaValidationErrors", schemaValidationErrors(bindingResult));
148	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
149	                .map(FieldError::getField)
150	                .distinct()
151	                .toList());
152	        }
153	        return ResponseEntity.status(status).body(detail);
154	    }
155	
156	    /**
157	     * Handles {@link RequiredFieldsMissingException} thrown when a request omits or leaves
158	     * blank one or more required fields. Returns a 400 Bad Request whose {@code errors}
159	     * property lists the name of each offending field.
160	     *
161	     * @param e The {@link RequiredFieldsMissingException} to be handled
162	     * @param request {@link HttpServletRequest} object referring to the current request.
163	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
164	     */
165	    @ExceptionHandler(RequiredFieldsMissingException.class)
166	    @ResponseBody
167	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
168	        HttpStatus status = HttpStatus.BAD_REQUEST;
169	        logger.debug("Missing or blank required fields at {} {}: {}",
170	            request.getMethod(),
171	            request.getRequestURI(),
172	            e.getFields());
173	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
174	        detail.setProperty("errors", e.getFields());
175	        return ResponseEntity.status(status).body(detail);
176	    }
177	
178	    /**
179	     * Handles {@link InvalidFieldsException} thrown when a request supplies one or more
180	     * fields whose value is present but fails a business rule (for example a telephone
181	     * that does not normalize to exactly ten digits). Returns a 400 Bad Request whose
182	     * {@code errors} property lists the name of each offending field.
183	     *
184	     * @param e The {@link InvalidFieldsException} to be handled
185	     * @param request {@link HttpServletRequest} object referring to the current request.
186	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
187	     */
188	    @ExceptionHandler(InvalidFieldsException.class)
189	    @ResponseBody
190	    public ResponseEntity<ProblemDetail> handleInvalidFieldsException(InvalidFieldsException e, HttpServletRequest request) {
191	        HttpStatus status = HttpStatus.BAD_REQUEST;
192	        logger.debug("Invalid field values at {} {}: {}",
193	            request.getMethod(),
194	            request.getRequestURI(),
195	            e.getFields());
196	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
197	        detail.setProperty("errors", e.getFields());
198	        return ResponseEntity.status(status).body(detail);
199	    }
200	
201	    /**
202	     * Handles {@link DuplicateTelephoneException} thrown when a request tries to create an owner
203	     * whose normalized telephone is already used by another owner. Returns a 409 Conflict.
204	     *
205	     * @param e The {@link DuplicateTelephoneException} to be handled
206	     * @param request {@link HttpServletRequest} object referring to the current request.
207	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
208	     */
209	    @ExceptionHandler(DuplicateTelephoneException.class)
210	    @ResponseBody
211	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
212	        HttpStatus status = HttpStatus.CONFLICT;
213	        logger.debug("Duplicate telephone at {} {}: {}",
214	            request.getMethod(),
215	            request.getRequestURI(),
216	            e.getMessage());
217	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
218	        return ResponseEntity.status(status).body(detail);
219	    }
220	
221	    /**
222	     * Handles {@link DuplicateHouseholdException} thrown when a request tries to create an owner
223	     * whose lastName and address already belong to another owner and the request has not opted in
224	     * via {@code sharesHousehold}. Returns a 409 Conflict.
225	     *
226	     * @param e The {@link DuplicateHouseholdException} to be handled
227	     * @param request {@link HttpServletRequest} object referring to the current request.
228	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
229	     */
230	    @ExceptionHandler(DuplicateHouseholdException.class)
231	    @ResponseBody
232	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
233	        HttpStatus status = HttpStatus.CONFLICT;
234	        logger.debug("Duplicate household at {} {}: {}",
235	            request.getMethod(),
236	            request.getRequestURI(),
237	            e.getMessage());
238	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
239	        return ResponseEntity.status(status).body(detail);
240	    }
241	
242	    /**
243	     * Handles {@link CityCapacityExceededException} thrown when a request tries to create an owner
244	     * whose city already contains the maximum number of owners. Returns a 409 Conflict.
245	     *
246	     * @param e The {@link CityCapacityExceededException} to be handled
247	     * @param request {@link HttpServletRequest} object referring to the current request.
248	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
249	     */
250	    @ExceptionHandler(CityCapacityExceededException.class)
251	    @ResponseBody
252	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
253	        HttpStatus status = HttpStatus.CONFLICT;
254	        logger.debug("City at capacity at {} {}: {}",
255	            request.getMethod(),
256	            request.getRequestURI(),
257	            e.getMessage());
258	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
259	        return ResponseEntity.status(status).body(detail);
260	    }
261	
262	    /**
263	     * Handles {@link DailyOwnerLimitExceededException} thrown when a request tries to create an owner
264	     * once the maximum number of owners for the current day has already been created. Returns a
265	     * 429 Too Many Requests.
266	     *
267	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
268	     * @param request {@link HttpServletRequest} object referring to the current request.
269	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
270	     */
271	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
272	    @ResponseBody
273	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
274	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
275	        logger.debug("Daily owner limit exceeded at {} {}: {}",
276	            request.getMethod(),
277	            request.getRequestURI(),
278	            e.getMessage());
279	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_EXCEEDED);
280	        return ResponseEntity.status(status).body(detail);
281	    }
282	
283	    /**
284	     * Renders the field-level errors of a {@link BindingResult} as the {@link ValidationMessageDto} list
285	     * exposed under the {@code schemaValidationErrors} property of the response.
286	     *
287	     * @param bindingResult The {@link BindingResult} carrying the rejected fields.
288	     * @return One {@link ValidationMessageDto} per field error.
289	     */
290	    private List<ValidationMessageDto> schemaValidationErrors(BindingResult bindingResult) {
291	        return bindingResult.getFieldErrors().stream()
292	            .map(fieldError -> {
293	                String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
294	                String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
295	                String message = "Field '%s' %s (rejected value: %s)".formatted(
296	                    fieldError.getField(),
297	                    defaultMessage,
298	                    rejectedValue);
299	                return new ValidationMessageDto(message)
300	                    .putAdditionalProperty("field", fieldError.getField())
301	                    .putAdditionalProperty("rejectedValue", rejectedValue)
302	                    .putAdditionalProperty("defaultMessage", defaultMessage);
303	            })
304	            .toList();
305	    }
306	
307	}
